def chart_confound():
    p = Plot((6.5, 15.5), (2.8, 6.8), xlab='поросят в гнезде при отъёме', ylab='масса при отъёме, кг', title='Гнёзда, раскрашенные по возрасту отъёма')
    young = lit.age <= 21
    old = lit.age >= 25
    mid = ~(young | old)
    p.points(lit.litter[mid], lit.wean[mid], color='var(--axis)', r=2.4, op=0.5)
    p.points(lit.litter[young], lit.wean[young], color='var(--series-1)', r=3.2)
    p.points(lit.litter[old], lit.wean[old], color='var(--series-2)', r=3.2)
    xs = np.array([6.5, 15.5])
    p.line(xs, 4.02699 + 0.0829 * xs, color='var(--text-1)', width=1.6, dash='6 4')
    for a, col in [(20, 'var(--series-1)'), (26, 'var(--series-2)')]:
        p.line(xs, M7['b0'] + M7['b_age'] * a + M7['b_lit'] * xs, color=col, width=2)
    p.text(6.7, 4.3, 'простая регрессия: +0,08')
    p.text(15.3, 3.45, 'отъём 20 дней', color='var(--series-1)', anchor='end')
    p.text(15.3, 6.6, 'отъём 26 дней', color='var(--series-2)', anchor='end')
    return figure([p.render('конфаундинг')], 'Синие точки — отъём до 21 дня, оранжевые — с 25 дней. Пунктир — простая регрессия по всем гнёздам: почти плоская. Внутри одного возраста (две сплошные прямые) больше поросят → каждый легче. Большие гнёзда чаще отнимали позже, а возраст сам добавляет массу — это и маскировало связь.')


