def chart_ancova():
    rng = np.random.default_rng(89)
    k = 45
    diet = np.repeat(['CON', 'PRO', 'ACID'], 15)
    start = np.round(rng.uniform(6, 10, k), 1)
    eff = {'CON': 0, 'PRO': 32, 'ACID': 14}
    adg = np.round(250 + 24 * start + np.array([eff[d] for d in diet]) + rng.normal(0, 18, k))
    p = Plot((5.8, 10.9), (360, 540), xlab='масса при постановке, кг', ylab='привес, г/сут', title='ANCOVA: три параллельные прямые')
    cols = {'CON': 'var(--axis)', 'ACID': 'var(--series-1)', 'PRO': 'var(--series-2)'}
    shift = {'CON': 0, 'ACID': A['b_acid'], 'PRO': A['b_pro']}
    xs = np.array([5.8, 10.15])
    for g in ['CON', 'ACID', 'PRO']:
        m = diet == g
        p.points(start[m], adg[m], color=cols[g], r=3)
        p.line(xs, A['b0'] + shift[g] + A['b_start'] * xs, color=cols[g], width=2)
    for g, c in [('PRO', 'var(--series-2)'), ('ACID', 'var(--series-1)'), ('CON', None)]:
        p.text(10.2, A['b0'] + shift[g] + A['b_start'] * 10.15, g, dy=4, color=c)
    return figure([p.render('ANCOVA')], 'Три рациона, по 15 станков. Наклон один на всех (24,2 г/сут на кг массы при постановке), прямые сдвинуты: PRO выше контроля на 32 г/сут, ACID — на 19 г/сут <b>при одинаковой массе при постановке</b>.')


